create role anon nologin;           -- quien no inició sesión
create role authenticated nologin;  -- quien sí inició sesión
create schema auth;
create function auth.uid() returns uuid language sql stable as
$$ select nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'sub','')::uuid $$;

create table public.notas (id serial primary key, autor uuid not null, texto text not null);
grant select, insert, update, delete on public.notas to authenticated;
grant select on public.notas to anon;

